<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Blaster '95</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #222; }
  body { font-family: 'Courier New', monospace; }
  #wrap { position: relative; width: 100vw; height: 100vh; }
  canvas { display: block; width: 100%; height: 100%; cursor: crosshair; }
  .overlay {
    position: absolute; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center; text-align: center;
    background: rgba(20, 10, 30, 0.82); color: #fff; z-index: 10;
  }
  .overlay.hidden { display: none; }
  .title {
    font-size: 64px; font-weight: bold; letter-spacing: 4px;
    color: #ffd23f; text-shadow: 4px 4px 0 #b34700, 8px 8px 0 rgba(0,0,0,.4);
    margin-bottom: 8px;
  }
  .subtitle { font-size: 20px; color: #9fd8ff; margin-bottom: 28px; }
  .btn {
    font-family: inherit; font-size: 26px; font-weight: bold; letter-spacing: 2px;
    padding: 14px 44px; color: #fff; background: #d33; border: 4px solid #fff;
    box-shadow: 0 6px 0 #7a1010; cursor: pointer; border-radius: 6px;
    transition: transform .05s;
  }
  .btn:hover { background: #e55; }
  .btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #7a1010; }
  .howto { margin-top: 26px; font-size: 16px; color: #ccc; line-height: 1.7; }
  .howto b { color: #ffd23f; }
  .big { font-size: 52px; font-weight: bold; color: #ffd23f; text-shadow: 3px 3px 0 #b34700; margin-bottom: 10px; }
  .scoreline { font-size: 26px; color: #fff; margin-bottom: 24px; }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="c"></canvas>
  <div id="startScreen" class="overlay">
    <div class="title">BALLOON BLASTER '95</div>
    <div class="subtitle">Level 1 &mdash; Pop 'em all</div>
    <button id="startBtn" class="btn">START</button>
    <div class="howto">
      <b>Aim</b> with the mouse &middot; <b>hold</b> to draw the bow, <b>release</b> to shoot<br>
      Pop <b>15</b> balloons to win &middot; miss <b>5</b> arrows and you lose
    </div>
  </div>
  <div id="endScreen" class="overlay hidden">
    <div class="big" id="endTitle">YOU WIN!</div>
    <div class="scoreline" id="endScore">Score: 0</div>
    <button id="againBtn" class="btn">PLAY AGAIN</button>
  </div>
</div>
<script>
(() => {
"use strict";
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
let W = 0, H = 0, DPR = 1;
function resize() {
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  canvas.width = W * DPR; canvas.height = H * DPR;
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
}
window.addEventListener('resize', resize);
resize();

// ---------- audio ----------
let AC = null;
function audio() {
  if (!AC) { try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {} }
  if (AC && AC.state === 'suspended') AC.resume();
  return AC;
}
function tone(freq, dur, type, vol, slideTo) {
  const ac = audio(); if (!ac) return;
  const t = ac.currentTime;
  const o = ac.createOscillator(), g = ac.createGain();
  o.type = type || 'sine'; o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(1, slideTo), t + dur);
  g.gain.setValueAtTime(vol || 0.2, t);
  g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
  o.connect(g); g.connect(ac.destination);
  o.start(t); o.stop(t + dur + 0.02);
}
function noiseBurst(dur, vol) {
  const ac = audio(); if (!ac) return;
  const t = ac.currentTime;
  const len = Math.max(1, Math.floor(ac.sampleRate * dur));
  const buf = ac.createBuffer(1, len, ac.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = ac.createBufferSource(); src.buffer = buf;
  const g = ac.createGain(); g.gain.setValueAtTime(vol || 0.3, t);

